package com.google.common.hash;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import org.junit.Test;

public class HashingConsistentHashTest {

  // Reimplementation of the pre-patch generator-based algorithm to verify equivalence.
  private static int oldConsistentHash(long input, int buckets) {
    if (buckets <= 0) {
      throw new IllegalArgumentException("buckets must be positive: " + buckets);
    }
    LinearCongruentialGenerator generator = new LinearCongruentialGenerator(input);
    int candidate = 0;
    while (true) {
      int next = (int) ((candidate + 1) / generator.nextDouble());
      if (next >= 0 && next < buckets) {
        candidate = next;
      } else {
        return candidate;
      }
    }
  }

  // Mirrors the removed inner class from the pre-patch implementation.
  private static final class LinearCongruentialGenerator {
    private long state;

    LinearCongruentialGenerator(long seed) {
      this.state = seed;
    }

    double nextDouble() {
      state = 2862933555777941757L * state + 1;
      return ((double) ((int) (state >>> 33) + 1)) / 0x1.0p31;
    }
  }

  @Test
  public void consistentHash_matchesOldImplementation_forVariousInputsAndBuckets() {
    long[] inputs = new long[] {
        0L,
        1L,
        -1L,
        Long.MIN_VALUE,
        Long.MAX_VALUE,
        0xCAFEBABEL,
        0xCAFEBABEDEADBEEFL,
        123456789L,
        98765432123456789L,
        -98765432123456789L
    };
    int[] bucketsArray = new int[] {1, 2, 3, 5, 10, 17, 64, 100, 256, 1000};

    for (long input : inputs) {
      for (int buckets : bucketsArray) {
        int expected = oldConsistentHash(input, buckets);
        int actual = Hashing.consistentHash(input, buckets);
        assertEquals(
            "Mismatch for input=" + input + " buckets=" + buckets, expected, actual);
      }
    }
  }

  @Test
  public void consistentHash_monotonicWhenAddingBucket() {
    long[] inputs = new long[] {
        0L,
        1L,
        2L,
        3L,
        4L,
        5L,
        -1L,
        -2L,
        0x123456789ABCDEFL,
        Long.MIN_VALUE,
        Long.MAX_VALUE - 1
    };

    for (long input : inputs) {
      int prev = Hashing.consistentHash(input, 1);
      for (int buckets = 1; buckets < 100; buckets++) {
        int curr = Hashing.consistentHash(input, buckets);
        int next = Hashing.consistentHash(input, buckets + 1);

        // Property of this consistent hashing algorithm:
        // When increasing the bucket count from b to b+1, the key either stays in the same
        // bucket or moves to the newly added bucket (index b).
        assertTrue(
            "For input=" + input + ", buckets=" + buckets + ": curr=" + curr + ", next=" + next,
            next == curr || next == buckets);

        prev = curr;
      }
    }
  }

  @Test
  public void consistentHash_bucketsMustBePositive() {
    try {
      Hashing.consistentHash(123L, 0);
      fail("Expected IllegalArgumentException for buckets=0");
    } catch (IllegalArgumentException expected) {
      // expected
    }
    try {
      Hashing.consistentHash(123L, -3);
      fail("Expected IllegalArgumentException for negative buckets");
    } catch (IllegalArgumentException expected) {
      // expected
    }
  }

  @Test
  public void consistentHash_hashCodeOverloadMatchesLongVersion() {
    long[] inputs = new long[] {0L, 1L, -1L, 42L, 1234567890L, Long.MIN_VALUE, Long.MAX_VALUE};
    int[] bucketsArray = new int[] {1, 2, 3, 10, 100};

    for (long input : inputs) {
      HashCode hc = Hashing.murmur3_128().hashLong(input);
      for (int buckets : bucketsArray) {
        // The HashCode-based overload should be consistent with using its long representation.
        int viaHashCode = Hashing.consistentHash(hc, buckets);
        int viaLong = Hashing.consistentHash(hc.asLong(), buckets);
        assertEquals(
            "Mismatch between HashCode and long overload for input=" + input + ", buckets=" + buckets,
            viaLong, viaHashCode);
      }
    }
  }
}

