package com.google.common.collect;

import junit.framework.TestCase;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;

public class IteratorsTransformJdkFunctionTest extends TestCase {

  public void testBasicTransformationWithJdkFunction() {
    Iterator<String> stringIterator = Arrays.asList("1", "2", "3").iterator();
    Function<String, Integer> parseInt = Integer::valueOf;

    Iterator<Integer> transformed = Iterators.transform(stringIterator, parseInt);

    List<Integer> result = new ArrayList<>();
    while (transformed.hasNext()) {
      result.add(transformed.next());
    }
    assertEquals(Arrays.asList(1, 2, 3), result);
  }

  public void testRemoveDelegationAndStateRulesWithJdkFunction() {
    List<String> list = new ArrayList<>(Arrays.asList("a", "bb", "ccc"));
    Iterator<String> base = list.iterator();
    Function<String, Integer> lengthFn = s -> s.length();

    Iterator<Integer> transformed = Iterators.transform(base, lengthFn);

    // First element
    assertTrue(transformed.hasNext());
    assertEquals(1, (int) transformed.next());
    transformed.remove();
    assertEquals(Arrays.asList("bb", "ccc"), list);

    // Calling remove twice without an intervening next() should throw
    try {
      transformed.remove();
      fail("Expected IllegalStateException on consecutive remove() without next()");
    } catch (IllegalStateException expected) {
      // expected
    }

    // Second element
    assertTrue(transformed.hasNext());
    assertEquals(2, (int) transformed.next());
    transformed.remove();
    assertEquals(Collections.singletonList("ccc"), list);

    // Third element
    assertTrue(transformed.hasNext());
    assertEquals(3, (int) transformed.next());
    transformed.remove();
    assertEquals(Collections.emptyList(), list);
  }

  public void testRemoveBeforeNextThrowsWithJdkFunction() {
    List<String> list = new ArrayList<>(Arrays.asList("x", "y"));
    Iterator<String> base = list.iterator();
    Function<String, String> identity = s -> s;

    Iterator<String> transformed = Iterators.transform(base, identity);

    try {
      transformed.remove();
      fail("Expected IllegalStateException when remove() is called before next()");
    } catch (IllegalStateException expected) {
      // expected
    }

    // Underlying list unchanged
    assertEquals(Arrays.asList("x", "y"), list);
  }

  public void testLazyApplicationWithJdkFunction() {
    List<String> list = new ArrayList<>(Arrays.asList("a", "b"));
    AtomicInteger applied = new AtomicInteger(0);
    Function<String, String> toUpperCounting =
        s -> {
          applied.incrementAndGet();
          return s.toUpperCase();
        };

    Iterator<String> transformed = Iterators.transform(list.iterator(), toUpperCounting);

    // No application yet
    assertEquals(0, applied.get());

    // hasNext should not trigger transformation
    assertTrue(transformed.hasNext());
    assertEquals(0, applied.get());

    // First element triggers one application
    assertEquals("A", transformed.next());
    assertEquals(1, applied.get());

    // Second element
    assertTrue(transformed.hasNext());
    assertEquals("B", transformed.next());
    assertEquals(2, applied.get());

    // Exhausted
    assertFalse(transformed.hasNext());
    assertEquals(2, applied.get());
  }
}

