package com.google.common.util.concurrent;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.FutureTask;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.Test;

public class RetryExecutorTest {

  @Test
  public void execute_nullTask_throwsNullPointerException() throws Exception {
    RetryExecutor executor = RetryExecutor.builder().build();
    try {
      executor.execute(null);
      fail("Expected NullPointerException");
    } catch (NullPointerException expected) {
      // expected
    }
  }

  @Test
  public void execute_succeedsAfterRetries_fixedBackoffZeroDelay() throws Exception {
    final AtomicInteger attempts = new AtomicInteger();
    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .backoffMillis(0) // minimal delay but still exercises sleep path
        .build();

    Callable<String> task = new Callable<String>() {
      @Override
      public String call() throws Exception {
        int a = attempts.getAndIncrement();
        if (a < 2) {
          throw new IOException("fail " + a);
        }
        return "ok";
      }
    };

    String result = executor.execute(task);
    assertEquals("ok", result);
    // 2 failures + 1 success = 3 attempts
    assertEquals(3, attempts.get());
  }

  @Test
  public void execute_nonRetryableException_thrownImmediately() throws Exception {
    final AtomicInteger attempts = new AtomicInteger();
    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(5)
        .backoffMillis(0)
        .retryOn(IOException.class) // only IOExceptions are retryable
        .build();

    Callable<String> task = new Callable<String>() {
      @Override
      public String call() {
        attempts.incrementAndGet();
        throw new IllegalStateException("non-retryable");
      }
    };

    try {
      executor.execute(task);
      fail("Expected IllegalStateException to be thrown immediately");
    } catch (IllegalStateException expected) {
      // expected
    }
    assertEquals("Should not retry on non-retryable exception", 1, attempts.get());
  }

  @Test
  public void execute_exhaustedRetries_throwsLastException() throws Exception {
    final AtomicInteger attempts = new AtomicInteger();
    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .backoffMillis(0)
        .build(); // no retryOn configured => all exceptions are retryable

    Callable<String> task = new Callable<String>() {
      @Override
      public String call() throws Exception {
        int a = attempts.getAndIncrement();
        throw new IOException("attempt " + a);
      }
    };

    try {
      executor.execute(task);
      fail("Expected IOException after exhausting retries");
    } catch (IOException e) {
      // The last attempt index is 2 (0-based) with maxRetries=3
      assertEquals("attempt 2", e.getMessage());
    }
    assertEquals(3, attempts.get());
  }

  @Test
  public void execute_exponentialBackoff_pathCovered_andSucceeds() throws Exception {
    final AtomicInteger attempts = new AtomicInteger();
    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .backoffMillis(1)       // small base delay
        .exponentialBackoff(true)
        .build();

    Callable<String> task = new Callable<String>() {
      @Override
      public String call() throws Exception {
        int a = attempts.getAndIncrement();
        if (a < 2) {
          throw new IOException("fail " + a);
        }
        return "done";
      }
    };

    String result = executor.execute(task);
    assertEquals("done", result);
    assertEquals(3, attempts.get());
  }

  @Test
  public void execute_retryOnSpecificException_doesNotRetryOnSubclass() throws Exception {
    final AtomicInteger attempts = new AtomicInteger();
    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(4)
        .backoffMillis(0)
        .retryOn(IOException.class) // Only exact IOException class is retryable per implementation
        .build();

    Callable<String> task = new Callable<String>() {
      @Override
      public String call() throws Exception {
        attempts.incrementAndGet();
        // Subclass of IOException; per implementation, not considered retryable (exact match only)
        throw new FileNotFoundException("subclass");
      }
    };

    try {
      executor.execute(task);
      fail("Expected FileNotFoundException");
    } catch (FileNotFoundException expected) {
      // expected
    }
    assertEquals("Should not retry on subclass when exact class is required", 1, attempts.get());
  }

  @Test
  public void execute_interruptedDuringSleep_throwsOriginalLastException() throws Exception {
    final AtomicInteger attempts = new AtomicInteger();

    final RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(5)
        .backoffMillis(200) // ensure there is enough time to interrupt during sleep
        .build();

    final Callable<String> task = new Callable<String>() {
      @Override
      public String call() throws Exception {
        attempts.incrementAndGet();
        throw new IOException("boom");
      }
    };

    FutureTask<String> future = new FutureTask<>(new Callable<String>() {
      @Override
      public String call() throws Exception {
        return executor.execute(task);
      }
    });
    Thread t = new Thread(future, "retry-exec-interrupt-test");
    t.start();

    // Wait until first attempt occurs
    long start = System.currentTimeMillis();
    while (attempts.get() < 1 && System.currentTimeMillis() - start < 2000) {
      Thread.sleep(5);
    }
    // Give a brief moment to enter sleep, then interrupt
    Thread.sleep(50);
    t.interrupt();

    try {
      future.get();
      fail("Expected IOException propagated after interruption");
    } catch (ExecutionException ee) {
      Throwable cause = ee.getCause();
      if (!(cause instanceof IOException)) {
        fail("Expected IOException, got: " + cause);
      }
      assertEquals("boom", cause.getMessage());
    }

    // Only the first attempt should have been made before interruption aborted retries
    assertEquals(1, attempts.get());
  }

  @Test
  public void builderValidation_maxRetriesMustBePositive() {
    try {
      RetryExecutor.builder().maxRetries(0).build();
      fail("Expected IllegalArgumentException for non-positive maxRetries");
    } catch (IllegalArgumentException expected) {
      // expected
    }
  }

  @Test
  public void builderValidation_backoffMillisMustBeNonNegative() {
    try {
      RetryExecutor.builder().backoffMillis(-1).build();
      fail("Expected IllegalArgumentException for negative backoffMillis");
    } catch (IllegalArgumentException expected) {
      // expected
    }
  }
}

