package com.google.common.util.concurrent;

import junit.framework.TestCase;

import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.FutureTask;

/**
 * Unit tests for RetryExecutor covering retry logic, backoff behavior,
 * retryable exception selection, builder validations, and interruption handling.
 */
public class RetryExecutorTest extends TestCase {

  public void testFixedBackoffRetriesAndSuccess() throws Exception {
    final int[] attempts = {0};
    Callable<String> task = new Callable<String>() {
      @Override
      public String call() throws Exception {
        attempts[0]++;
        if (attempts[0] <= 2) {
          throw new IOException("transient failure");
        }
        return "ok";
      }
    };

    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .backoffMillis(50)
        .exponentialBackoff(false)
        .retryOn(IOException.class)
        .build();

    long start = System.nanoTime();
    String result = executor.execute(task);
    long elapsedMs = (System.nanoTime() - start) / 1_000_000;

    assertEquals("ok", result);
    assertEquals(3, attempts[0]); // two failures then success

    // Fixed backoff of 50ms, two sleeps expected -> at least ~100ms elapsed
    assertTrue("Expected elapsed >= 90ms but was " + elapsedMs, elapsedMs >= 90);
  }

  public void testExponentialBackoffDelaysIncrease() throws Exception {
    final int[] attempts = {0};
    Callable<String> task = new Callable<String>() {
      @Override
      public String call() throws Exception {
        attempts[0]++;
        if (attempts[0] <= 2) {
          throw new IOException("transient failure");
        }
        return "ok";
      }
    };

    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .backoffMillis(50)
        .exponentialBackoff(true)
        .retryOn(IOException.class)
        .build();

    long start = System.nanoTime();
    String result = executor.execute(task);
    long elapsedMs = (System.nanoTime() - start) / 1_000_000;

    assertEquals("ok", result);
    assertEquals(3, attempts[0]); // two failures then success

    // Exponential backoff: 50ms + 100ms = 150ms expected minimum sleep time
    assertTrue("Expected elapsed >= 130ms but was " + elapsedMs, elapsedMs >= 130);
  }

  public void testNonRetryableExceptionThrownImmediately() {
    final int[] attempts = {0};
    Callable<String> task = new Callable<String>() {
      @Override
      public String call() {
        attempts[0]++;
        throw new NullPointerException("boom");
      }
    };

    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(5)
        .backoffMillis(200) // would be significant if any retry happened
        .exponentialBackoff(false)
        .retryOn(IOException.class) // only IOExceptions are retryable
        .build();

    long start = System.nanoTime();
    try {
      executor.execute(task);
      fail("Expected NullPointerException to be thrown immediately");
    } catch (Exception e) {
      assertTrue(e instanceof NullPointerException);
    }
    long elapsedMs = (System.nanoTime() - start) / 1_000_000;

    assertEquals(1, attempts[0]); // no retries
    assertTrue("Should not have waited for backoff; elapsed was " + elapsedMs, elapsedMs < 100);
  }

  public void testExhaustedRetriesThrowsLastException() {
    final int[] attempts = {0};
    final IOException last = new IOException("last");
    Callable<String> task = new Callable<String>() {
      @Override
      public String call() throws Exception {
        attempts[0]++;
        if (attempts[0] == 2) {
          throw last; // ensure identity of last exception
        }
        throw new IOException("first");
      }
    };

    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(2)
        .backoffMillis(30)
        .exponentialBackoff(false)
        .retryOn(IOException.class)
        .build();

    long start = System.nanoTime();
    try {
      executor.execute(task);
      fail("Expected IOException after exhausting retries");
    } catch (Exception e) {
      assertSame("Should throw the last encountered exception", last, e);
    }
    long elapsedMs = (System.nanoTime() - start) / 1_000_000;

    assertEquals(2, attempts[0]); // exactly maxRetries attempts
    assertTrue("Expected at least one backoff sleep; elapsed was " + elapsedMs, elapsedMs >= 25);
  }

  public void testRetryOnSubclassNotMatched() {
    final int[] attempts = {0};
    Callable<String> task = new Callable<String>() {
      @Override
      public String call() throws Exception {
        attempts[0]++;
        throw new FileNotFoundException("subclass of IOException");
      }
    };

    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .backoffMillis(200)
        .retryOn(IOException.class) // exact class match required; subclass not included
        .build();

    try {
      executor.execute(task);
      fail("Expected FileNotFoundException to be thrown immediately (not retryable by exact match)");
    } catch (Exception e) {
      assertTrue(e instanceof FileNotFoundException);
    }
    assertEquals(1, attempts[0]); // no retries due to non-matching exact class
  }

  public void testRetryAllWhenNoExceptionsConfigured() throws Exception {
    final int[] attempts = {0};
    Callable<String> task = new Callable<String>() {
      @Override
      public String call() {
        attempts[0]++;
        if (attempts[0] < 2) {
          throw new NullPointerException("transient");
        }
        return "done";
      }
    };

    // No retryOn configured -> all exceptions are retryable
    RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .backoffMillis(0) // avoid sleeps for speed
        .build();

    String result = executor.execute(task);
    assertEquals("done", result);
    assertEquals(2, attempts[0]); // retried once after NPE
  }

  public void testBuilderValidation() {
    try {
      RetryExecutor.builder().maxRetries(0).build();
      fail("Expected IllegalArgumentException for maxRetries <= 0");
    } catch (IllegalArgumentException expected) {
      // expected
    }

    try {
      RetryExecutor.builder().backoffMillis(-1).build();
      fail("Expected IllegalArgumentException for negative backoffMillis");
    } catch (IllegalArgumentException expected) {
      // expected
    }

    try {
      RetryExecutor.builder().retryOn(null);
      fail("Expected NullPointerException for null retryOn class");
    } catch (NullPointerException expected) {
      // expected
    }
  }

  public void testThreadInterruptedDuringSleepThrowsLastException() throws Exception {
    final IOException failure = new IOException("fail-and-interrupt");
    Callable<Object> task = new Callable<Object>() {
      @Override
      public Object call() throws Exception {
        throw failure;
      }
    };

    final RetryExecutor executor = RetryExecutor.builder()
        .maxRetries(3)
        .backoffMillis(500) // long enough window to interrupt during sleep
        .exponentialBackoff(false)
        .retryOn(IOException.class)
        .build();

    FutureTask<Object> future = new FutureTask<>(new Callable<Object>() {
      @Override
      public Object call() throws Exception {
        return executor.execute(task);
      }
    });

    Thread t = new Thread(future, "retry-interrupt-test");
    t.start();

    // Give the task a moment to fail the first time and enter sleep, then interrupt.
    Thread.sleep(100);
    t.interrupt();

    try {
      future.get();
      fail("Expected IOException propagated after interruption during backoff sleep");
    } catch (ExecutionException ee) {
      Throwable cause = ee.getCause();
      assertTrue("Expected cause to be the original failure", cause instanceof IOException);
      assertEquals("fail-and-interrupt", cause.getMessage());
    }
  }
}

