import java.io.IOException;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.Test;

public class RetryExecutorTest {

  @Test
  public void testExecuteSucceedsAfterRetriesWithFixedZeroBackoff() throws Exception {
    final AtomicInteger attempts = new AtomicInteger(0);

    RetryExecutor executor =
        RetryExecutor.builder()
            .maxRetries(3)
            .backoffMillis(0) // ensure no sleep to keep test fast
            .exponentialBackoff(false)
            .retryOn(IOException.class)
            .build();

    Callable<String> task =
        new Callable<String>() {
          @Override
          public String call() throws Exception {
            int count = attempts.incrementAndGet();
            if (count < 3) {
              throw new IOException("transient failure " + count);
            }
            return "success";
          }
        };

    String result = executor.execute(task);
    assertEquals("success", result);
    // Should have attempted exactly 3 times: two failures and a final success.
    assertEquals(3, attempts.get());
  }

  @Test
  public void testNonRetryableExceptionIsThrownImmediately() {
    final AtomicInteger attempts = new AtomicInteger(0);

    RetryExecutor executor =
        RetryExecutor.builder()
            .maxRetries(5) // large to ensure it would retry if it were retryable
            .backoffMillis(0)
            .exponentialBackoff(false)
            .retryOn(IOException.class) // only retry on IOException
            .build();

    Callable<Object> task =
        new Callable<Object>() {
          @Override
          public Object call() {
            attempts.incrementAndGet();
            throw new NullPointerException("non-retryable");
          }
        };

    try {
      executor.execute(task);
      fail("Expected NullPointerException to be thrown immediately");
    } catch (Exception e) {
      assertTrue(e instanceof NullPointerException);
      // Verify that it did not retry.
      assertEquals(1, attempts.get());
    }
  }

  @Test
  public void testExponentialBackoffSleepsExpectedTotalTime() {
    final AtomicInteger attempts = new AtomicInteger(0);

    // Configure for exponential backoff with base 10ms.
    RetryExecutor executor =
        RetryExecutor.builder()
            .maxRetries(3) // attempts: 0,1,2 -> sleeps after 0 and 1
            .backoffMillis(10)
            .exponentialBackoff(true)
            .retryOn(IOException.class)
            .build();

    Callable<Object> task =
        new Callable<Object>() {
          @Override
          public Object call() throws Exception {
            attempts.incrementAndGet();
            throw new IOException("always fail");
          }
        };

    long start = System.currentTimeMillis();
    try {
      executor.execute(task);
      fail("Expected IOException after exhausting retries");
    } catch (Exception e) {
      assertTrue(e instanceof IOException);
    }
    long duration = System.currentTimeMillis() - start;

    // With exponential backoff: delays should be 10ms (2^0 * 10) + 20ms (2^1 * 10) = 30ms total.
    // Assert at least the expected sleep time elapsed.
    assertTrue("Duration " + duration + "ms should be >= 30ms", duration >= 30);
    assertEquals(3, attempts.get());
  }

