  public void testBackoffMillisSetterAffectsFixedDelay() {
    final AtomicInteger attempts = new AtomicInteger(0);

    // Fixed backoff of 20ms, two total attempts -> single sleep of ~20ms between attempts.
    RetryExecutor executor =
        RetryExecutor.builder()
            .maxRetries(2)
            .backoffMillis(20)
            .exponentialBackoff(false)
            .retryOn(IOException.class)
            .build();

    Callable<Object> task =
        new Callable<Object>() {
