    assertTrue("Duration " + duration + "ms should be >= 20ms", duration >= 20);
    assertEquals(2, attempts.get());
  }

  @Test
  public void testNegativeBackoffMillisRejectedByBuilder() {
    try {
      RetryExecutor.builder()
          .maxRetries(1)
          .backoffMillis(-1)
          .build();
      fail("Expected IllegalArgumentException for negative backoffMillis");
    } catch (IllegalArgumentException expected) {
      // expected
    }
  }
}

