            .maxRetries(3)
            .backoffMillis(0) // avoid delays in tests
            .build();

    AtomicInteger attempts = new AtomicInteger();
    Callable<String> task =
        () -> {
          int c = attempts.incrementAndGet();
          if (c < 3) {
            throw new RuntimeException("fail " + c);
          }
          return "success";
        };

    String result = executor.execute(task);
    assertEquals("success", result);
    assertEquals("Expected exactly 3 attempts (2 failures + 1 success)", 3, attempts.get());
  }

