  public void execute_retryOnExactIOException_retriesAndSucceeds() throws Exception {
    RetryExecutor executor =
        RetryExecutor.builder()
            .maxRetries(3)
            .backoffMillis(0) // avoid delays in tests
            .retryOn(IOException.class)
            .build();

    AtomicInteger attempts = new AtomicInteger();
    Callable<String> task =
        () -> {
          int c = attempts.incrementAndGet();
          if (c < 3) {
            throw new IOException("io fail " + c);
          }
          return "ok";
        };

    String result = executor.execute(task);
    assertEquals("ok", result);
    assertEquals("Expected 3 attempts (2 IOException retries + 1 success)", 3, attempts.get());
  }

