  public void execute_retryOnIOException_doesNotRetryOnSubclass_fileNotFound() {
    RetryExecutor executor =
        RetryExecutor.builder()
            .maxRetries(5)
            .backoffMillis(0) // avoid delays in tests
            .retryOn(IOException.class) // only exact IOException should be retried
            .build();

    AtomicInteger attempts = new AtomicInteger();
    Callable<String> task =
        () -> {
          attempts.incrementAndGet();
          throw new FileNotFoundException("not found");
        };

    try {
      executor.execute(task);
      fail("Expected FileNotFoundException to be thrown immediately without retries");
    } catch (Exception e) {
      // Because isRetryable checks exact class equality, FileNotFoundException is not retryable.
      if (!(e instanceof FileNotFoundException)) {
        fail("Expected FileNotFoundException but got: " + e);
      }
      assertEquals("Expected exactly one attempt for non-retryable exception", 1, attempts.get());
    }
  }

  @Test
  public void execute_nonRetryableRuntimeException_thrownImmediately() {
    RetryExecutor executor =
        RetryExecutor.builder()
            .maxRetries(4)
            .backoffMillis(0)
            .retryOn(IOException.class) // only retry IOException, not RuntimeException
            .build();

    AtomicInteger attempts = new AtomicInteger();
    Callable<String> task =
        () -> {
          attempts.incrementAndGet();
          throw new RuntimeException("boom");
        };

    try {
      executor.execute(task);
      fail("Expected RuntimeException to be thrown immediately without retries");
    } catch (Exception e) {
      if (!(e instanceof RuntimeException)) {
        fail("Expected RuntimeException but got: " + e);
      }
      assertEquals("Expected exactly one attempt for non-retryable exception", 1, attempts.get());
    }
  }

  @Test
  public void execute_exhaustedRetries_throwsLastException() {
    RetryExecutor executor =
        RetryExecutor.builder()
            .maxRetries(3)
            .backoffMillis(0) // avoid delays in tests
            .build(); // no retryOn => all exceptions retryable

    AtomicInteger attempts = new AtomicInteger();
    Callable<String> task =
        () -> {
          int c = attempts.incrementAndGet();
          throw new Exception("attempt " + c);
        };

    try {
      executor.execute(task);
      fail("Expected exception after exhausting retries");
    } catch (Exception e) {
      // After 3 attempts, last exception should be from attempt 3.
      assertEquals("attempt 3", e.getMessage());
      assertEquals("Expected exactly 3 attempts when all retries are exhausted", 3, attempts.get());
    }
  }
}

