package com.google.common.collect;

import static org.junit.Assert.*;

import org.junit.Test;

public class EvictingQueueAddZeroSizeTest {

  @Test
  public void add_whenMaxSizeZero_returnsFalseAndDoesNotModify() {
    EvictingQueue<String> q = EvictingQueue.create(0);

    assertEquals(0, q.size());
    assertTrue(q.isEmpty());

    boolean added = q.add("hello");

    assertFalse("add must return false when maxSize == 0", added);
    assertEquals("Queue size must remain 0 when maxSize == 0", 0, q.size());
    assertTrue("Queue must remain empty when maxSize == 0", q.isEmpty());
    assertFalse("Queue must not contain the element when maxSize == 0", q.contains("hello"));
  }

  @Test
  public void offer_whenMaxSizeZero_returnsFalseAndDoesNotModify() {
    EvictingQueue<String> q = EvictingQueue.create(0);

    boolean offered = q.offer("world");

    assertFalse("offer must return false when maxSize == 0", offered);
    assertEquals("Queue size must remain 0 when maxSize == 0", 0, q.size());
    assertTrue("Queue must remain empty when maxSize == 0", q.isEmpty());
    assertFalse("Queue must not contain the element when maxSize == 0", q.contains("world"));
  }

  @Test(expected = NullPointerException.class)
  public void add_nullElementStillChecked_whenMaxSizeZero() {
    EvictingQueue<Object> q = EvictingQueue.create(0);
    // Even with maxSize == 0, null elements are rejected via checkNotNull(e)
    q.add(null);
  }

  @Test
  public void add_whenMaxSizePositive_returnsTrueAndContains() {
    EvictingQueue<String> q = EvictingQueue.create(2);

    boolean added = q.add("a");

    assertTrue("add must return true when element is added", added);
    assertEquals(1, q.size());
    assertTrue(q.contains("a"));
  }

  @Test
  public void add_whenFull_evictsHeadAndReturnsTrue() {
    EvictingQueue<Integer> q = EvictingQueue.create(2);
    q.add(1);
    q.add(2);

    boolean added = q.add(3);

    assertTrue("add must return true when queue is modified", added);
    assertEquals("Queue size must remain at max size after eviction", 2, q.size());
    assertFalse("Head element must be evicted when adding to full queue", q.contains(1));
    assertTrue(q.contains(2));
    assertTrue(q.contains(3));
  }
}

