package com.google.common.eventbus;

import static org.junit.Assert.*;

import com.google.common.eventbus.Subscribe;
import com.google.common.io.BaseEncoding;
import java.io.IOException;
import java.io.OutputStream;
import java.io.StringWriter;
import org.junit.Test;

/**
 * Tests that cover the patch changes:
 * 1) EventBus Subscriber now catches StackOverflowError and forwards it to the SubscriberExceptionHandler.
 * 2) BaseEncoding.encodingStream enforces closed state and throws IOException on write/flush after close,
 *    with idempotent close behavior.
 */
public class SubscriberAndBaseEncodingPatchTest {

  @Test
  public void testSubscriberThrowsStackOverflowErrorHandledByExceptionHandler() {
    RecordingSubscriberExceptionHandler handler = new RecordingSubscriberExceptionHandler();
    EventBus bus = new EventBus(handler);

    Object event = new Object();
    bus.register(new StackOverflowingSubscriber());

    // Posting should not throw; the StackOverflowError must be handled by the handler.
    bus.post(event);

    // Verify the handler received the StackOverflowError and context is correct.
    assertNotNull("Expected the handler to capture an exception", handler.captured);
    assertTrue(
        "Expected a StackOverflowError to be captured",
        handler.captured instanceof StackOverflowError);
    assertNotNull("Expected a non-null exception context", handler.context);
    assertSame("Context should reference the same EventBus", bus, handler.context.getEventBus());
    assertSame("Context should reference the event that was posted", event, handler.context.getEvent());
    assertNotNull("Context should include the subscriber object", handler.context.getSubscriber());
    assertNotNull("Context should include the subscriber method", handler.context.getSubscriberMethod());
  }

  @Test
  public void testBaseEncodingEncodingStreamClosedBehavior() throws Exception {
    StringWriter out = new StringWriter();
    OutputStream os = BaseEncoding.base64().encodingStream(out);

    // Write some bytes to ensure encoder has buffered state.
    os.write(0x61); // 'a'
    os.write(0x62); // 'b'

