package com.google.common.collect;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.common.base.Function;
import com.google.common.base.Functions;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Spliterator;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.Test;

public class ListsTransformSpliteratorTest {

  private static final int CHAR_MASK =
      Spliterator.IMMUTABLE
          | Spliterator.CONCURRENT
          | Spliterator.ORDERED
          | Spliterator.SIZED
          | Spliterator.SUBSIZED;

  @Test
  public void copyOnWriteArrayList_spliteratorCharacteristicsPropagate() {
    CopyOnWriteArrayList<Integer> backing = new CopyOnWriteArrayList<>(Arrays.asList(1, 2, 3, 4));

    // Use a non-identity mapping to make sure mapping is applied by the spliterator.
    Function<Integer, Integer> doubleFn =
        new Function<Integer, Integer>() {
          @Override
          public Integer apply(Integer input) {
            return input * 2;
          }
        };

    List<Integer> transformed = Lists.transform(backing, doubleFn);

    Spliterator<Integer> backingSpliterator = backing.spliterator();
    Spliterator<Integer> transformedSpliterator = transformed.spliterator();

    // The transformed view must preserve key characteristics from the backing list's spliterator.
    int expected = backingSpliterator.characteristics() & CHAR_MASK;
    int actual = transformedSpliterator.characteristics() & CHAR_MASK;
    assertEquals("Transformed spliterator characteristics should match backing spliterator", expected, actual);

    // Specifically, CopyOnWriteArrayList should convey IMMUTABLE, which must be preserved.
    assertTrue(
        "Transformed spliterator should be IMMUTABLE when backing is CopyOnWriteArrayList",
        (actual & Spliterator.IMMUTABLE) != 0);

    // Size estimation should be preserved as well.
    assertEquals(
        "estimateSize should be preserved",
        backingSpliterator.estimateSize(),
        transformedSpliterator.estimateSize());

    // Validate that mapping is applied and order is preserved by the spliterator.
    List<Integer> seen = new ArrayList<>();
    transformedSpliterator.forEachRemaining(seen::add);
    assertEquals(Arrays.asList(2, 4, 6, 8), seen);
  }

  @Test
  public void linkedList_spliteratorCharacteristicsPropagate() {
    LinkedList<String> backing = new LinkedList<>(Arrays.asList("a", "b", "c", "d"));

    Function<String, String> toUpper =
        new Function<String, String>() {
          @Override
          public String apply(String input) {
            return input.toUpperCase();
          }
        };

    List<String> transformed = Lists.transform(backing, toUpper);

    Spliterator<String> backingSpliterator = backing.spliterator();
    Spliterator<String> transformedSpliterator = transformed.spliterator();

    int expected = backingSpliterator.characteristics() & CHAR_MASK;
    int actual = transformedSpliterator.characteristics() & CHAR_MASK;
    assertEquals("Transformed spliterator characteristics should match backing spliterator", expected, actual);

    // LinkedList's spliterator is ORDERED, SIZED, and SUBSIZED.
    assertTrue("ORDERED should be preserved", (actual & Spliterator.ORDERED) != 0);
    assertTrue("SIZED should be preserved", (actual & Spliterator.SIZED) != 0);
    assertTrue("SUBSIZED should be preserved", (actual & Spliterator.SUBSIZED) != 0);

    // Also verify estimateSize mirrors backing.
    assertEquals(backingSpliterator.estimateSize(), transformedSpliterator.estimateSize());
  }

  @Test
  public void copyOnWriteArrayList_concurrentIterationDoesNotThrow() throws Exception {
    // This test exercises the runtime behavior that motivated the change: When the transformed
    // view preserves IMMUTABLE from CopyOnWriteArrayList, stream iteration should be safe under
    // concurrent modifications (no ConcurrentModificationException).
    CopyOnWriteArrayList<Integer> backing = new CopyOnWriteArrayList<>();
    List<Integer> transformed = Lists.transform(backing, Functions.identity());

    AtomicBoolean stop = new AtomicBoolean(false);
    Thread writer =
        new Thread(
            () -> {
              int i = 0;
              while (!stop.get()) {
                for (int k = 0; k < 100; k++) {
                  backing.add(i++);
                }
                // Periodically clear to create structural changes while iteration may be ongoing.
                backing.clear();
              }
            },
            "cow-writer");
    writer.start();

    try {
      // Perform several iterations over the transformed view while the writer mutates the backing.
      // With proper spliterator characteristics (IMMUTABLE), this should not throw.
      for (int r = 0; r < 200; r++) {
        transformed.stream().forEach(x -> {});
      }
    } finally {
      stop.set(true);
      writer.join();
    }
  }
}

