    Spliterator<String> backingSpliterator = backing.spliterator();
    Spliterator<String> transformedSpliterator = transformed.spliterator();

    int expected = backingSpliterator.characteristics() & CHAR_MASK;
    int actual = transformedSpliterator.characteristics() & CHAR_MASK;
    assertEquals("Transformed spliterator characteristics should match backing spliterator", expected, actual);

    // LinkedList's spliterator is ORDERED, SIZED, and SUBSIZED.
    assertTrue("ORDERED should be preserved", (actual & Spliterator.ORDERED) != 0);
    assertTrue("SIZED should be preserved", (actual & Spliterator.SIZED) != 0);
    assertTrue("SUBSIZED should be preserved", (actual & Spliterator.SUBSIZED) != 0);

    // Also verify estimateSize mirrors backing.
    assertEquals(backingSpliterator.estimateSize(), transformedSpliterator.estimateSize());
  }

  @Test
  public void copyOnWriteArrayList_concurrentIterationDoesNotThrow() throws Exception {
    // This test exercises the runtime behavior that motivated the change: When the transformed
    // view preserves IMMUTABLE from CopyOnWriteArrayList, stream iteration should be safe under
    // concurrent modifications (no ConcurrentModificationException).
    CopyOnWriteArrayList<Integer> backing = new CopyOnWriteArrayList<>();
    List<Integer> transformed = Lists.transform(backing, Functions.identity());

    AtomicBoolean stop = new AtomicBoolean(false);
    Thread writer =
        new Thread(
            () -> {
              int i = 0;
              while (!stop.get()) {
                for (int k = 0; k < 100; k++) {
                  backing.add(i++);
                }
                // Periodically clear to create structural changes while iteration may be ongoing.
                backing.clear();
              }
            },
            "cow-writer");
    writer.start();

    try {
      // Perform several iterations over the transformed view while the writer mutates the backing.
      // With proper spliterator characteristics (IMMUTABLE), this should not throw.
      for (int r = 0; r < 200; r++) {
        transformed.stream().forEach(x -> {});
      }
    } finally {
      stop.set(true);
      writer.join();
    }
  }
}

