import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.PrimitiveIterator;
import java.util.Spliterator;
import org.junit.Test;

public class PrimitiveIteratorExposureTest {

  @Test
  public void intAsList_iteratorIsPrimitiveAndIteratesCorrectly() {
    List<Integer> list = ImmutableIntArray.of(10, 20, 30).asList();
    Iterator<Integer> it = list.iterator();
    assertTrue("Iterator should be a PrimitiveIterator.OfInt", it instanceof PrimitiveIterator.OfInt);

    PrimitiveIterator.OfInt pit = (PrimitiveIterator.OfInt) it;
    assertTrue(pit.hasNext());
    assertEquals(10, pit.nextInt());
    assertTrue(pit.hasNext());
    assertEquals(20, pit.nextInt());
    assertTrue(pit.hasNext());
    assertEquals(30, pit.nextInt());
    assertFalse(pit.hasNext());

    // Also verify boxed iteration path is consistent
    Iterator<Integer> boxed = list.iterator();
    assertEquals(Integer.valueOf(10), boxed.next());
    assertEquals(Integer.valueOf(20), boxed.next());
    assertEquals(Integer.valueOf(30), boxed.next());
    assertFalse(boxed.hasNext());
  }

  @Test
  public void longAsList_iteratorIsPrimitiveAndIteratesCorrectly() {
    List<Long> list = ImmutableLongArray.of(1L, 2L, 3L, 4L).asList();
    Iterator<Long> it = list.iterator();
    assertTrue("Iterator should be a PrimitiveIterator.OfLong", it instanceof PrimitiveIterator.OfLong);

    PrimitiveIterator.OfLong pit = (PrimitiveIterator.OfLong) it;
    long[] expected = {1L, 2L, 3L, 4L};
    int i = 0;
    while (pit.hasNext()) {
      assertEquals("Unexpected value at index " + i, expected[i], pit.nextLong());
      i++;
    }
    assertEquals("Should have iterated all elements", expected.length, i);
  }

  @Test
  public void doubleAsList_iteratorIsPrimitiveAndIteratesCorrectly() {
