    assertTrue("Iterator should be a PrimitiveIterator.OfDouble", it instanceof PrimitiveIterator.OfDouble);

    PrimitiveIterator.OfDouble pit = (PrimitiveIterator.OfDouble) it;
    double[] expected = {1.5, -2.0, 0.0, 42.25};
    int i = 0;
    while (pit.hasNext()) {
      assertEquals("Unexpected value at index " + i, expected[i], pit.nextDouble(), 0.0);
      i++;
    }
    assertEquals("Should have iterated all elements", expected.length, i);
  }

  @Test
  public void primitiveIterator_removeIsUnsupported() {
    // int
    PrimitiveIterator.OfInt intIt = (PrimitiveIterator.OfInt) ImmutableIntArray.of(1, 2).asList().iterator();
    try {
      intIt.remove();
      fail("remove() should be unsupported for PrimitiveIterator.OfInt");
    } catch (UnsupportedOperationException expected) {
      // expected
    }

