    PrimitiveIterator.OfLong longIt =
        (PrimitiveIterator.OfLong) ImmutableLongArray.of(1L, 2L).asList().iterator();
    try {
      longIt.remove();
      fail("remove() should be unsupported for PrimitiveIterator.OfLong");
    } catch (UnsupportedOperationException expected) {
      // expected
    }

