        (PrimitiveIterator.OfDouble) ImmutableDoubleArray.of(1.0, 2.0).asList().iterator();
    try {
      doubleIt.remove();
      fail("remove() should be unsupported for PrimitiveIterator.OfDouble");
    } catch (UnsupportedOperationException expected) {
      // expected
    }
  }

  @Test
  public void asList_spliteratorIsPrimitiveSpliterator() {
    // Even when viewed through List<E>, the spliterator should be an instance of the primitive type
    List<Integer> intList = ImmutableIntArray.of(7, 8, 9).asList();
    Spliterator<?> intSpliterator = intList.spliterator();
    assertTrue("Spliterator should be Spliterator.OfInt", intSpliterator instanceof Spliterator.OfInt);

    List<Long> longList = ImmutableLongArray.of(10L, 20L).asList();
    Spliterator<?> longSpliterator = longList.spliterator();
    assertTrue("Spliterator should be Spliterator.OfLong", longSpliterator instanceof Spliterator.OfLong);

    List<Double> doubleList = ImmutableDoubleArray.of(3.14, 2.72).asList();
    Spliterator<?> doubleSpliterator = doubleList.spliterator();
    assertTrue("Spliterator should be Spliterator.OfDouble", doubleSpliterator instanceof Spliterator.OfDouble);
  }

  @Test
  public void primitiveIterator_forEachRemainingConsumesAll() {
    // int
    PrimitiveIterator.OfInt intIt =
        (PrimitiveIterator.OfInt) ImmutableIntArray.of(1, 2, 3, 4).asList().iterator();
    final int[] sum = {0};
    intIt.forEachRemaining((int v) -> sum[0] += v);
    assertEquals(1 + 2 + 3 + 4, sum[0]);

    // long
    PrimitiveIterator.OfLong longIt =
        (PrimitiveIterator.OfLong) ImmutableLongArray.of(5L, 6L, 7L).asList().iterator();
    final long[] lsum = {0L};
    longIt.forEachRemaining((long v) -> lsum[0] += v);
    assertEquals(5L + 6L + 7L, lsum[0]);

    // double
    PrimitiveIterator.OfDouble doubleIt =
        (PrimitiveIterator.OfDouble) ImmutableDoubleArray.of(1.0, 2.5, -0.5).asList().iterator();
    final double[] dsum = {0.0};
    doubleIt.forEachRemaining((double v) -> dsum[0] += v);
    assertEquals(1.0 + 2.5 - 0.5, dsum[0], 0.0);
  }
}

